def compare_versions(a: str, b: str) -> int:
    """
    Compare two semantic version strings a and b.
    Return -1 if a < b, 0 if equal, 1 if a > b.
    """
    def parse(v: str):
        """Return (major, minor, patch, pre_release_list) where pre_release_list is list of identifiers."""
        # remove build metadata
        if '+' in v:
            v, _ = v.split('+', 1)
        # split pre-release
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core = v
            pre_ids = []
        major, minor, patch = map(int, core.split('.'))
        return major, minor, patch, pre_ids

    def cmp_ident(a_id: str, b_id: str) -> int:
        """Compare two pre-release identifiers."""
        a_num = a_id.isdigit()
        b_num = b_id.isdigit()
        if a_num and b_num:
            a_int = int(a_id)
            b_int = int(b_id)
            return (a_int > b_int) - (a_int < b_int)
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        # both non-numeric
        return (a_id > b_id) - (a_id < b_id)

    a_m, a_mi, a_p, a_pre = parse(a)
    b_m, b_mi, b_p, b_pre = parse(b)

    # compare core numeric parts
    for a_val, b_val in ((a_m, b_m), (a_mi, b_mi), (a_p, b_p)):
        if a_val != b_val:
            return 1 if a_val > b_val else -1

    # at this point numeric parts equal
    if not a_pre and not b_pre:
        return 0
    if not a_pre:
        # a has no pre-release, higher precedence
        return 1
    if not b_pre:
        return -1

    # compare pre-release identifiers
    for a_id, b_id in zip(a_pre, b_pre):
        comp = cmp_ident(a_id, b_id)
        if comp != 0:
            return comp
    # all compared identifiers equal; longer pre-release is higher
    if len(a_pre) == len(b_pre):
        return 0
    return 1 if len(a_pre) > len(b_pre) else -1
